function printResourceReceipt(row:StoredResource,kind:"customerInvoices"|"printers"){
 const language=document.documentElement.lang;
 const translateUi=(value:string)=>uiText(value,language==="en"||language==="fr"?language:"ar");

 const popup=window.open("","_blank","width=440,height=680");
 if(!popup)throw new Error(translateUi("اسمح بالنوافذ المنبثقة لطباعة المستند."));
 const doc=popup.document;
 doc.title=kind==="printers"?translateUi("اختبار الطابعة"):translateUi("فاتورة العميل");
 const style=doc.createElement("style");
 const width=String(kind==="printers"?row.data.paperWidth:row.data.receiptPaperWidth)==="58"?"58":"80";
 style.textContent="@page{size:"+width+"mm auto;margin:3mm}body{font:13px Arial,sans-serif;direction:"+(language==="ar"?"rtl":"ltr")+";max-width:calc("+width+"mm - 6mm);margin:0 auto;color:#111}h2{text-align:center}section{border-top:1px dashed #777;padding:8px 0}p{overflow-wrap:anywhere;margin:7px 0}small{display:block;text-align:center}";
 doc.head.appendChild(style);
 const title=doc.createElement("h2");title.textContent=kind==="printers"?translateUi("اختبار إعداد الطابعة"):translateUi("فاتورة العميل");doc.body.appendChild(title);
 if(kind==="printers"&&row.data.headerText){const header=doc.createElement("p");header.textContent=String(row.data.headerText);doc.body.appendChild(header);}
 const heading=doc.createElement("p");heading.textContent=row.name;doc.body.appendChild(heading);
 const section=doc.createElement("section");doc.body.appendChild(section);
 const fields=kind==="printers"?[[translateUi("الاتصال"),row.data.connection],[translateUi("العنوان"),row.data.address],[translateUi("عرض الورق"),row.data.paperWidth],[translateUi("وقت الطباعة"),row.data.printOn],[translateUi("نسخ الطباعة"),row.data.copies]]:[[translateUi("العملة"),row.currency??"SAR"],[translateUi("اسم المنشأة"),row.data.sellerName],[translateUi("بريد المنشأة"),row.data.sellerEmail],[translateUi("العنوان"),row.data.sellerAddress],[translateUi("الرقم الضريبي"),row.data.sellerTaxNumber],[translateUi("محتوى QR المخصص"),row.data.qrText],[translateUi("رقم الفاتورة"),row.data.invoiceNumber],[translateUi("المبلغ قبل الضريبة"),row.data.subtotal],[translateUi("الضريبة"),row.data.taxAmount],[translateUi("رسوم الخدمة"),row.data.serviceFee],[translateUi("الإجمالي"),(Number(row.data.subtotal||0)+Number(row.data.taxAmount||0)+Number(row.data.serviceFee||0)).toFixed(2)],[translateUi("الحالة"),row.status]];
 for(const [label,value] of fields){const p=doc.createElement("p");p.textContent=label+": "+String(value??"—");section.appendChild(p);}
 if(kind==="printers"&&row.data.footerText){const custom=doc.createElement("p");custom.textContent=String(row.data.footerText);doc.body.appendChild(custom);}
 const footer=doc.createElement("small");footer.textContent=new Date().toLocaleString("en-GB",{numberingSystem:"latn"});doc.body.appendChild(footer);
 popup.focus();popup.print();
}
